const trace=[];for(let r=0;r<5;r++){try{if(2===r)throw new Error("at "+r);trace.push("ok:"+r)}finally{if(2===r){trace.push("finally-continue-suppresses-throw:"+r);continue}}trace.push("after-try:"+r)}print(trace.join(" | "));const trace2=[];for(let r=0;r<10;r++)try{if(3===r)throw new Error("stop");trace2.push("iter:"+r)}finally{if(3===r){trace2.push("finally-break-suppresses-throw");break}}print(trace2.join(" | "));